/* personal-drive-image-index-data.js
 * Indice "<nome_do_arquivo>.png" -> ID do arquivo no Google Drive, pra pasta
 * PESSOAL do usuario (Meu Drive > Sorcery > images > alp/art/bet/dra/got/pro).
 * Esta e a UNICA fonte de imagens do app - o indice oficial
 * (drive-image-index-data.js) nao e mais usado na resolucao de imagens
 * (ver imageResolver.js e README, secao "Onde vem as imagens das cartas").
 *
 * Formato do nome de arquivo: "{setcode}-{nome_com_underscore}-{tag}-{finish}.png".
 * Para Alpha/Beta/Arthurian Legends/Dragonlord/Gothic o tag e sempre "b"; para
 * Promo o tag varia por carta/tiragem (ex "op", "d", "wk", "ai", "scg",
 * "tc", "k", "dk") - por isso o resolvedor usa uma logica separada pra
 * Promo (agrupa por nome e escolhe foil/standard pelo sufixo final do
 * nome do arquivo, ver imageResolver.js).
 *
 * Cartas que nao tem correspondencia exata pelo nome (ex.: apostrofo,
 * variacoes de grafia) usam um fallback por nome mais proximo (fuzzy
 * match) dentro do mesmo set - e se a similaridade for baixa demais,
 * o resolvedor cai no placeholder em vez de arriscar uma imagem errada
 * (ver imageResolver.js, findClosestPersonalMatch).
 *
 * window.SEED_PERSONAL_DRIVE_IMAGE_INDEX e copiado pra
 * data.personalDriveImageIndex (ver state.js) apenas na primeira vez que o
 * app roda - depois disso, o indice salvo nos dados do usuario e que vale.
 *
 * Estado atual: 3082 imagens, coletadas em 2026-08-04 varrendo por completo
 * as subpastas alp (817), art (452), bet (812), dra (26), got (891)
 * e pro (84) da pasta pessoal do usuario no Drive.
 */
